extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_main_scene()
	if not check("basket", basket != null, "La scena basket.tscn deve caricarsi correttamente"):
		return
	var stars: Array[Node] = []
	for child in basket.get_children():
		if child is Sprite2D and child != basket:
			stars.append(child)
	if not check("star_count", stars.size() == 5, "Il cesto deve contenere esattamente 5 stelle create dal codice"):
		return
	var star_0: Sprite2D = stars[0] as Sprite2D
	var star_4: Sprite2D = stars[4] as Sprite2D
	check("star_spacing", star_4.position.x > star_0.position.x and star_4.position.y > star_0.position.y, "Le stelle devono avere posizioni X e Y crescenti calcolate con l'indice del ciclo")
